var PGTPOP_CONTEUDO_MODULO = "<style>\n/* Variáveis de cor do módulo — faltavam 8 delas (--accent, --accent-2,\n   --input, --panel, --shadow-soft, --text-strong, --muted-2, --surface-2),\n   causando texto sem contraste e cartões sem fundo em toda a tela (bug\n   real encontrado em 2026-08-21). As demais (--bg, --text, --border etc.)\n   já vinham do tema global do Portal e continuam assim. */\n#tplPgtPopContainer {\n  --accent: var(--bc-action);\n  --accent-2: var(--bc-action);\n  --input: #FFFFFF;\n  --panel: var(--bc-surface);\n  --shadow-soft: none;\n  --text-strong: var(--bc-text);\n  --muted-2: var(--bc-text-3);\n  --surface-2: var(--bc-surface-2);\n}\n#tplPgtPopContainer, #tplPgtPopContainer body {\n  font-family: var(--bc-sans);\n}\n\n/* Manual do Operador — mesmo padrão visual dos outros módulos do Portal */\n#tplPgtPopContainer .manual-wrap { max-width: 900px; margin: 0 auto; padding: 18px 18px 60px; line-height: 1.6; }\n#tplPgtPopContainer .manual-wrap h1 { font-size: 26px; margin-bottom: 4px; }\n#tplPgtPopContainer .manual-wrap .subtitulo { color: var(--muted); margin-top: 0; margin-bottom: 22px; }\n#tplPgtPopContainer .manual-wrap h2 { font-size: 19px; margin-top: 40px; padding-bottom: 8px; border-bottom: 1px solid var(--border); color: var(--text-strong); }\n#tplPgtPopContainer .manual-wrap h3 { font-size: 15px; margin-top: 26px; color: var(--accent-2); }\n#tplPgtPopContainer .manual-wrap p { color: var(--text); }\n#tplPgtPopContainer .manual-wrap table { width: 100%; border-collapse: collapse; margin: 14px 0 22px; font-size: 13.5px; }\n#tplPgtPopContainer .manual-wrap th, #tplPgtPopContainer .manual-wrap td { border: 1px solid var(--border); padding: 8px 10px; text-align: left; vertical-align: top; }\n#tplPgtPopContainer .manual-wrap th { background: #FFFFFF; color: var(--text-strong); }\n#tplPgtPopContainer .manual-wrap tr:nth-child(even) td { background: var(--bc-surface-2); }\n#tplPgtPopContainer .callout { background: var(--bc-action-bg); border: 1px solid var(--bc-action-line); border-left: 4px solid var(--accent); border-radius: var(--radius-sm); padding: 12px 14px; margin: 14px 0; font-size: 13.5px; }\n#tplPgtPopContainer .callout strong { color: var(--text-strong); }\n#tplPgtPopContainer .manual-wrap ol, #tplPgtPopContainer .manual-wrap ul { padding-left: 22px; }\n#tplPgtPopContainer .manual-wrap ol li, #tplPgtPopContainer .manual-wrap ul li { margin-bottom: 6px; }\n#tplPgtPopContainer .toc { background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px 20px; margin-bottom: 30px; }\n#tplPgtPopContainer .toc h2 { margin-top: 0; border-bottom: none; font-size: 15px; }\n#tplPgtPopContainer .toc ol { columns: 2; column-gap: 30px; }\n#tplPgtPopContainer .toc a { text-decoration: none; color: var(--accent-2); cursor: pointer; }\n#tplPgtPopContainer .toc a:hover { text-decoration: underline; }\n#tplPgtPopContainer .topo-link { display: inline-block; margin-top: 30px; }\n\n#tplPgtPopContainer * { box-sizing: border-box; }\n#tplPgtPopContainer img { max-width: 100%; }\n#tplPgtPopContainer a { color: var(--accent-2); }\n#tplPgtPopContainer .hidden { display: none !important; }\n#tplPgtPopContainer .wrap { max-width: 100%; margin: 0; padding: 18px; }\n#tplPgtPopContainer .header-card {\n  background: #FFFFFF;\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  padding: 14px 18px;\n  box-shadow: var(--shadow-soft);\n  margin-bottom: 14px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 14px;\n}\n#tplPgtPopContainer .title-area h1 { margin: 0; font-size: 19px; color: var(--text-strong); font-weight: 800; }\n#tplPgtPopContainer .title-area p { margin: 5px 0 0; color: var(--muted); font-size: 13px; }\n#tplPgtPopContainer .step-nav { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }\n#tplPgtPopContainer .step-nav-item {\n  flex: 1; min-width: 110px; text-align: center; padding: 8px 6px; border-radius: var(--radius-sm);\n  background: var(--surface-2); border: 1px solid var(--border); color: var(--muted); font-size: 11.5px; font-weight: 700;\n}\n#tplPgtPopContainer .step-nav-item.active { background: var(--accent); color: var(--text-strong); border-color: var(--accent); }\n#tplPgtPopContainer .step-nav-item.done { color: var(--success); border-color: var(--success); }\n#tplPgtPopContainer .step { display: none; }\n#tplPgtPopContainer .step.active { display: block; }\n#tplPgtPopContainer .panel {\n  background: #FFFFFF;\n  border-radius: var(--radius); padding: 18px; box-shadow: var(--shadow-soft); border: 1px solid var(--border);\n}\n#tplPgtPopContainer .panel h2 {\n  margin: 0 0 16px; font-size: 14px; color: var(--text-strong); border-bottom: 1px solid var(--border);\n  padding-bottom: 11px; text-transform: uppercase;\n}\n#tplPgtPopContainer .section-divider {\n  margin: 22px 0 14px; padding: 8px 10px; border: 1px solid var(--border); border-left: 3px solid var(--accent-2);\n  background: #FFFFFF; border-radius: 6px; font-size: 12px; font-weight: 800; color: var(--info);\n  text-transform: uppercase;\n}\n#tplPgtPopContainer .form-row { display: flex; gap: 12px; margin-bottom: 12px; flex-wrap: wrap; }\n#tplPgtPopContainer .form-group { flex: 1; min-width: 160px; }\n#tplPgtPopContainer .form-group.w-100 { flex: 1 1 100%; }\n#tplPgtPopContainer .form-group label { display: block; margin-bottom: 6px; font-size: 12px; font-weight: 700; color: var(--text); }\n#tplPgtPopContainer .form-control {\n  width: 100%; min-height: 30px; padding: 5px 9px; border: 1px solid var(--border); border-radius: var(--radius-sm);\n  font-size: 12.5px; color: var(--text); background: var(--input);\n}\n#tplPgtPopContainer textarea.form-control { min-height: 70px; resize: vertical; font-family: inherit; }\n#tplPgtPopContainer .form-control:focus { outline: none; border-color: var(--accent-2); }\n#tplPgtPopContainer .field-help { display: block; margin-top: 6px; font-size: 11px; color: var(--muted-2); line-height: 1.45; }\n#tplPgtPopContainer .btn {\n  padding: 7px 14px; border: 1px solid transparent; border-radius: var(--radius-sm); font-weight: 800;\n  font-size: 12.5px; cursor: pointer; min-height: 30px;\n}\n#tplPgtPopContainer .btn:disabled { opacity: 0.55; cursor: not-allowed; }\n#tplPgtPopContainer .btn-primary { background: var(--accent); color: var(--text-strong); }\n#tplPgtPopContainer .btn-secondary { background: var(--card-soft); color: var(--text-strong); border: 1px solid var(--border); }\n#tplPgtPopContainer .btn-danger { background: var(--danger); color: #fff; }\n#tplPgtPopContainer .btn-xs { padding: 4px 10px; min-height: 24px; font-size: 11px; }\n#tplPgtPopContainer .btn-container { display: flex; gap: 10px; margin-top: 18px; flex-wrap: wrap; }\n#tplPgtPopContainer .alert-box { margin-top: 14px; border-radius: var(--radius-sm); padding: 9px 11px; font-size: 12px; border: 1px solid transparent; }\n#tplPgtPopContainer .alert-box.info { background: var(--bc-info-bg); color: var(--info); border-color: var(--bc-info-line); }\n#tplPgtPopContainer .alert-box.warning { background: var(--bc-warn-bg); color: var(--warning); border-color: var(--bc-warn-line); }\n#tplPgtPopContainer .alert-box.error { background: var(--bc-danger-bg); color: var(--danger); border-color: var(--bc-danger-line); }\n#tplPgtPopContainer .alert-box.success { background: var(--bc-action-bg); color: var(--success); border-color: var(--bc-action-line); }\n#tplPgtPopContainer .pop-card {\n  background: var(--surface-2); border: 1px solid var(--border); border-radius: var(--radius-sm);\n  padding: 10px 12px; margin-bottom: 8px;\n}\n#tplPgtPopContainer .pop-card-head { display: flex; align-items: center; gap: 8px; }\n#tplPgtPopContainer .pop-card-head label { flex: 1; font-size: 12.5px; color: var(--text-strong); font-weight: 700; cursor: pointer; margin: 0; }\n#tplPgtPopContainer .pop-card-codigo { font-size: 10.5px; color: var(--muted); font-weight: 700; min-width: 52px; }\n#tplPgtPopContainer .pop-card-extra { margin-top: 8px; margin-left: 26px; }\n#tplPgtPopContainer .pop-avulso-item {\n  display: flex; align-items: center; gap: 10px; background: var(--surface-2); border: 1px solid var(--border);\n  border-radius: 6px; padding: 8px 10px; font-size: 12px; color: var(--text-strong); margin-bottom: 8px;\n}\n#tplPgtPopContainer .pop-avulso-item .avulso-nome { flex: 1; }\n#tplPgtPopContainer .doc-item {\n  display: flex; align-items: center; gap: 10px; background: var(--surface-2); border: 1px solid var(--border);\n  border-radius: var(--radius-sm); padding: 10px 12px; margin-bottom: 8px; flex-wrap: wrap;\n}\n#tplPgtPopContainer .doc-item .doc-titulo { flex: 1; min-width: 200px; font-size: 12.5px; color: var(--text-strong); font-weight: 700; }\n#tplPgtPopContainer .doc-item .doc-tipo {\n  font-size: 10px; font-weight: 800; padding: 3px 8px; border-radius: 999px; text-transform: uppercase;\n  background: var(--bc-info-bg); color: var(--info);\n}\n#tplPgtPopContainer .doc-item .doc-tipo.pop { background: var(--bc-action-bg); color: var(--success); }\n#tplPgtPopContainer .terminal-wrap { margin-top: 12px; border-radius: var(--radius-sm); overflow: hidden; border: 1px solid var(--border); }\n#tplPgtPopContainer .terminal-header { background: var(--bg); color: var(--muted); padding: 8px 12px; font-size: 10.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .4px; border-bottom: 1px solid var(--border); }\n#tplPgtPopContainer .terminal { background: var(--bg); color: var(--success); padding: 10px 12px; font-family: var(--bc-mono); font-size: 11.5px; max-height: 220px; overflow-y: auto; white-space: pre-wrap; }\n#tplPgtPopContainer .terminal .erro { color: var(--danger); font-weight: 800; }\n#tplPgtPopContainer .terminal .aviso { color: var(--warning); font-weight: 800; }\n#tplPgtPopContainer .img-slot-list { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 8px; }\n#tplPgtPopContainer .img-slot {\n  width: 110px; background: var(--card-soft); border: 1px solid var(--border); border-radius: 6px; padding: 6px;\n}\n#tplPgtPopContainer .img-slot img { width: 100%; height: 64px; object-fit: cover; border-radius: 4px; margin-bottom: 4px; }\n#tplPgtPopContainer .img-slot input { width: 100%; font-size: 10px; padding: 3px 5px; min-height: 22px; }\n#tplPgtPopContainer .img-slot button { width: 100%; margin-top: 4px; }\n#tplPgtPopContainer table.lista-doc { width:100%; border-collapse: collapse; font-size: 12px; margin-top: 8px; }\n#tplPgtPopContainer table.lista-doc th, #tplPgtPopContainer table.lista-doc td { border: 1px solid var(--border); padding: 6px 9px; text-align: left; color: var(--text); }\n#tplPgtPopContainer table.lista-doc th { background: var(--card-soft); color: var(--text-strong); }\n@media (max-width: 768px) {\n  #tplPgtPopContainer .wrap { padding: 10px; }\n  #tplPgtPopContainer .panel { padding: 14px; }\n  #tplPgtPopContainer .step-nav-item { min-width: 90px; font-size: 10.5px; }\n}\n</style>\n\n<script>\n  const TPL_PGTPOP_HTML_ = `\n  <div id=\"tplPgtPop_viewModulo\">\n  <div class=\"wrap\">\n    <header class=\"header-card\">\n      <div class=\"title-area\">\n        <h1 id=\"tplPgtPop_appTitulo\">PGT e POP</h1>\n        <p>Gera o PGTS e os Procedimentos Operacionais Padrão, no padrão real da Metrolabs, personalizados para cada hospital.</p>\n      </div>\n      <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplPgtPop_abrirManual_()\">Manual do Operador</button>\n    </header>\n\n    <div class=\"step-nav\">\n      <div class=\"step-nav-item active\" id=\"tplPgtPop_nav1\">1. Hospital</div>\n      <div class=\"step-nav-item\" id=\"tplPgtPop_nav2\">2. PGT</div>\n      <div class=\"step-nav-item\" id=\"tplPgtPop_nav3\">3. POPs</div>\n      <div class=\"step-nav-item\" id=\"tplPgtPop_nav4\">4. Gerar</div>\n      <div class=\"step-nav-item\" id=\"tplPgtPop_nav5\">5. Documentos</div>\n    </div>\n\n    <div class=\"panel\">\n\n      <div class=\"step active\" id=\"tplPgtPop_step1\">\n        <h2>1. Dados do Hospital</h2>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label>CNPJ</label>\n            <input id=\"tplPgtPop_cnpj\" class=\"form-control\" placeholder=\"00.000.000/0000-00\">\n          </div>\n          <div class=\"form-group\" style=\"flex: 0 0 auto; align-self: flex-end;\">\n            <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplPgtPop_buscarCNPJ()\" id=\"tplPgtPop_btnBuscarCnpj\">Buscar</button>\n          </div>\n          <div class=\"form-group\" style=\"flex: 0 0 auto; align-self: flex-end;\">\n            <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplPgtPop_consultarDocumentosExistentes_()\" id=\"tplPgtPop_btnConsultarDocs\">Consultar documentos já gerados</button>\n          </div>\n        </div>\n        <div id=\"tplPgtPop_alertaCnpj\"></div>\n        <div id=\"tplPgtPop_docsExistentesWrap\"></div>\n        <div class=\"form-row\">\n          <div class=\"form-group w-100\">\n            <label>Razão Social / Nome do Hospital</label>\n            <input id=\"tplPgtPop_hospital\" class=\"form-control\" placeholder=\"Nome do Hospital\">\n          </div>\n        </div>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label>Logradouro</label>\n            <input id=\"tplPgtPop_logradouro\" class=\"form-control\">\n          </div>\n          <div class=\"form-group\">\n            <label>Bairro</label>\n            <input id=\"tplPgtPop_bairro\" class=\"form-control\">\n          </div>\n        </div>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label>Cidade</label>\n            <input id=\"tplPgtPop_cidade\" class=\"form-control\">\n          </div>\n          <div class=\"form-group\">\n            <label>UF</label>\n            <input id=\"tplPgtPop_uf\" class=\"form-control\" maxlength=\"2\">\n          </div>\n        </div>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label>Porte / Tipo do Hospital</label>\n            <input id=\"tplPgtPop_porte\" class=\"form-control\" placeholder=\"Ex.: Hospital geral de médio porte\">\n          </div>\n          <div class=\"form-group\">\n            <label>Nº de Leitos</label>\n            <input id=\"tplPgtPop_leitos\" class=\"form-control\" type=\"number\" min=\"0\">\n          </div>\n        </div>\n        <div class=\"section-divider\">Aprovação (Responsável Técnico do Hospital)</div>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label>Nome do Responsável Técnico</label>\n            <input id=\"tplPgtPop_aprovadorNome\" class=\"form-control\" placeholder=\"Ex.: Maria da Silva\">\n          </div>\n          <div class=\"form-group\">\n            <label>Cargo</label>\n            <input id=\"tplPgtPop_aprovadorCargo\" class=\"form-control\" placeholder=\"Ex.: Responsável Técnico\">\n          </div>\n        </div>\n        <span class=\"field-help\">Este nome entra como \"Aprovado por\" no rodapé de cada documento — é quem assina pela instituição.</span>\n        <div class=\"section-divider\">Elaborado por</div>\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label>Nome de quem elaborou</label>\n            <input id=\"tplPgtPop_elaboradoPorNome\" class=\"form-control\">\n          </div>\n          <div class=\"form-group\">\n            <label>Cargo</label>\n            <input id=\"tplPgtPop_elaboradoPorCargo\" class=\"form-control\" placeholder=\"Ex.: Engenheiro Clínico\">\n          </div>\n          <div class=\"form-group\">\n            <label>Registro profissional</label>\n            <input id=\"tplPgtPop_elaboradoPorRegistro\" class=\"form-control\" placeholder=\"Ex.: REA-GO 00000/D-GO\">\n          </div>\n        </div>\n        <span class=\"field-help\">Nome, cargo e registro são de quem elaborou ESTE documento específico — os 3 campos mudam juntos, nunca deixe o registro de uma pessoa em um documento assinado por outra. \"Revisado por\" continua sempre fixo (Charles Hytley Santos Teixeira).</span>\n        <div class=\"btn-container\">\n          <button type=\"button\" class=\"btn btn-primary\" onclick=\"tplPgtPop_irParaEtapa(2)\">Avançar</button>\n        </div>\n      </div>\n\n      <div class=\"step\" id=\"tplPgtPop_step2\">\n        <h2>2. PGT — Plano de Gerenciamento de Tecnologias em Saúde</h2>\n        <p style=\"color: var(--muted); font-size: 12.5px;\">Documento único deste hospital. Se quiser guiar a IA numa estrutura específica, descreva no roteiro abaixo — se deixar em branco, a IA monta a estrutura completa sozinha (Escopo, Finalidade, Justificativa, Termos e Definições, Inventário, Manutenção, etc.).</p>\n        <div class=\"form-row\">\n          <div class=\"form-group w-100\">\n            <label>Roteiro / Observações do PGT (opcional)</label>\n            <textarea id=\"tplPgtPop_roteiroPgt\" class=\"form-control\" placeholder=\"Ex.: dar ênfase em gestão de contratos terceirizados; incluir uma seção sobre o parque de ventiladores pulmonares...\"></textarea>\n          </div>\n        </div>\n        <div class=\"form-row\">\n          <div class=\"form-group w-100\">\n            <label>Imagens (opcional, com legenda e interpretação técnica por IA)</label>\n            <input type=\"file\" accept=\"image/*\" multiple onchange=\"tplPgtPop_addImagensPgt_(this)\">\n            <div id=\"tplPgtPop_imagensPgtWrap\"></div>\n          </div>\n        </div>\n        <div class=\"btn-container\">\n          <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplPgtPop_irParaEtapa(1)\">Voltar</button>\n          <button type=\"button\" class=\"btn btn-primary\" onclick=\"tplPgtPop_irParaEtapa(3)\">Avançar</button>\n        </div>\n      </div>\n\n      <div class=\"step\" id=\"tplPgtPop_step3\">\n        <h2>3. POPs — Procedimentos Operacionais Padrão</h2>\n        <p style=\"color: var(--muted); font-size: 12.5px;\">Marque os POPs que se aplicam a este hospital. Cada um tem roteiro opcional e até 4+ imagens opcionais (com legenda e interpretação técnica gerada pela IA).</p>\n        <div id=\"tplPgtPop_catalogoPops\"></div>\n        <div class=\"section-divider\">Adicionar POP avulso (fora do catálogo)</div>\n        <div class=\"form-row\">\n          <div class=\"form-group w-100\">\n            <label>Nome do POP</label>\n            <input id=\"tplPgtPop_avulsoNome\" class=\"form-control\" placeholder=\"Ex.: POP de Gerenciamento de Gases Medicinais\">\n          </div>\n        </div>\n        <div class=\"btn-container\">\n          <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplPgtPop_addPopAvulso()\">+ Adicionar POP avulso</button>\n        </div>\n        <div id=\"tplPgtPop_listaAvulsos\"></div>\n        <div class=\"btn-container\">\n          <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplPgtPop_irParaEtapa(2)\">Voltar</button>\n          <button type=\"button\" class=\"btn btn-primary\" onclick=\"tplPgtPop_irParaEtapa(4)\">Avançar</button>\n        </div>\n      </div>\n\n      <div class=\"step\" id=\"tplPgtPop_step4\">\n        <h2>4. Gerar Documentos</h2>\n        <p style=\"color: var(--muted); font-size: 12.5px;\">A IA gera 1 documento por vez (o PGT, depois cada POP selecionado) — pode levar alguns minutos dependendo da quantidade.</p>\n        <div id=\"tplPgtPop_resumoGeracao\"></div>\n        <div class=\"btn-container\">\n          <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplPgtPop_irParaEtapa(3)\">Voltar</button>\n          <button type=\"button\" class=\"btn btn-primary\" id=\"tplPgtPop_btnGerar\" onclick=\"tplPgtPop_gerarTudo()\">Gerar Tudo</button>\n        </div>\n        <div class=\"btn-container\">\n          <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplPgtPop_irParaEtapa(5)\">Ver Documentos</button>\n        </div>\n      </div>\n\n      <div class=\"step\" id=\"tplPgtPop_step5\">\n        <h2>5. Documentos Gerados</h2>\n        <div id=\"tplPgtPop_listaDocumentos\"></div>\n        <div class=\"section-divider\">Lista de Documentos deste hospital (controle)</div>\n        <div class=\"btn-container\">\n          <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplPgtPop_carregarListaControle_()\">Atualizar lista</button>\n        </div>\n        <div id=\"tplPgtPop_listaControle\"></div>\n        <div class=\"btn-container\">\n          <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplPgtPop_irParaEtapa(3)\">Voltar aos POPs</button>\n        </div>\n      </div>\n\n      <div class=\"section-divider\">Histórico da operação</div>\n      <div class=\"terminal-wrap\">\n        <div class=\"terminal-header\">Histórico da operação (visível em todas as etapas)</div>\n        <div class=\"terminal\" id=\"tplPgtPop_terminalLog\">Aguardando...</div>\n      </div>\n      <div class=\"btn-container\">\n        <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplPgtPop_limparLog()\">Limpar histórico</button>\n      </div>\n\n    </div>\n  </div>\n  </div>\n\n  <div id=\"tplPgtPop_viewManual\" style=\"display:none\">\n  <div class=\"wrap manual-wrap\">\n\n    <header class=\"header-card\" style=\"position:static; margin-bottom:24px;\">\n      <div class=\"title-area\">\n        <h1 style=\"margin-bottom:4px;\">Manual do Operador</h1>\n        <p style=\"margin:0;\">PGT e POP — Engenharia Clínica — geração de Plano de Gerenciamento de Tecnologias em Saúde e Procedimentos Operacionais Padrão</p>\n      </div>\n      <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplPgtPop_voltarDoManual_()\">← Voltar ao sistema</button>\n    </header>\n\n    <div class=\"toc\" id=\"tplPgtPop_topoManual\">\n      <h2>Índice</h2>\n      <ol>\n        <li><a onclick=\"tplPgtPop_irParaSecao_('tplPgtPop_ms1')\">Como usar este manual</a></li>\n        <li><a onclick=\"tplPgtPop_irParaSecao_('tplPgtPop_ms2')\">O que este sistema faz</a></li>\n        <li><a onclick=\"tplPgtPop_irParaSecao_('tplPgtPop_ms3')\">Etapa 1 — Dados do Hospital</a></li>\n        <li><a onclick=\"tplPgtPop_irParaSecao_('tplPgtPop_ms4')\">Etapa 2 — PGT</a></li>\n        <li><a onclick=\"tplPgtPop_irParaSecao_('tplPgtPop_ms5')\">Etapa 3 — POPs</a></li>\n        <li><a onclick=\"tplPgtPop_irParaSecao_('tplPgtPop_ms6')\">Etapa 4 — Gerar Documentos</a></li>\n        <li><a onclick=\"tplPgtPop_irParaSecao_('tplPgtPop_ms7')\">Etapa 5 — Documentos Gerados</a></li>\n        <li><a onclick=\"tplPgtPop_irParaSecao_('tplPgtPop_ms8')\">Passo a passo completo</a></li>\n        <li><a onclick=\"tplPgtPop_irParaSecao_('tplPgtPop_ms9')\">Erros comuns</a></li>\n        <li><a onclick=\"tplPgtPop_irParaSecao_('tplPgtPop_ms10')\">Glossário</a></li>\n      </ol>\n    </div>\n\n    <h2 id=\"tplPgtPop_ms1\">1. Como usar este manual</h2>\n    <p>Este manual foi escrito para quem <strong>nunca usou o sistema</strong>. Leia na ordem, de cima para baixo, seguindo a tela também de cima para baixo. Se aparecer uma palavra técnica desconhecida, vá direto ao <strong>Glossário</strong> (seção 10).</p>\n\n    <h2 id=\"tplPgtPop_ms2\">2. O que este sistema faz, em uma frase</h2>\n    <p>Você preenche os dados de um hospital e o sistema gera, com ajuda de Inteligência Artificial, o <strong>PGT</strong> (Plano de Gerenciamento de Tecnologias em Saúde) inteiro e os <strong>POPs</strong> (Procedimentos Operacionais Padrão) escolhidos — todos personalizados pra aquele hospital, seguindo a RDC nº 509/2021 (ANVISA) e a ABNT NBR 15.943:2011.</p>\n    <div class=\"callout\"><strong>PGT é um documento grande e denso</strong> — é gerado em 6 blocos de Inteligência Artificial (não 1 chamada só), o que deixa o texto bem mais completo, mas também demora — pode levar alguns minutos. É normal a tela mostrar \"gerando...\" por um tempo.</div>\n\n    <h2 id=\"tplPgtPop_ms3\">3. Etapa 1 — Dados do Hospital</h2>\n    <table>\n      <tr><th>Campo</th><th>O que fazer</th></tr>\n      <tr><td>CNPJ</td><td>Digite e clique em \"Buscar\" — preenche Razão Social, Logradouro, Bairro, Cidade, UF sozinho</td></tr>\n      <tr><td>Porte / Tipo do Hospital</td><td>Ex.: hospital de grande porte, clínica, etc.</td></tr>\n      <tr><td>Nº de Leitos</td><td>Quantidade de leitos do hospital</td></tr>\n      <tr><td>Nome do Responsável Técnico</td><td>Quem é o responsável técnico do hospital (aparece no documento)</td></tr>\n      <tr><td>Cargo</td><td>Cargo desse responsável</td></tr>\n    </table>\n    <p>Use o botão <strong>\"Consultar documentos já gerados\"</strong> pra ver se esse hospital já tem PGT/POPs gerados antes, sem precisar gerar de novo.</p>\n\n    <h2 id=\"tplPgtPop_ms4\">4. Etapa 2 — PGT</h2>\n    <table>\n      <tr><th>Campo</th><th>O que fazer</th></tr>\n      <tr><td>Nome de quem elaborou</td><td>Nome de quem está montando o documento agora</td></tr>\n      <tr><td>Cargo</td><td>Sugestão: \"Gestor de Engenharia Clínica\" — pode editar</td></tr>\n      <tr><td>Registro profissional</td><td>Nº de registro (CREA, etc.) de quem elaborou</td></tr>\n      <tr><td>Roteiro / Observações do PGT (opcional)</td><td>Texto livre com informações específicas desse hospital que a IA deve considerar</td></tr>\n      <tr><td>Imagens (opcional)</td><td>Anexe fotos relevantes — a IA analisa e escreve uma interpretação técnica de cada uma, sozinha</td></tr>\n    </table>\n    <div class=\"callout\"><strong>Atenção com nome/cargo/registro:</strong> esses 3 campos são sempre editáveis e nunca vêm fixos — um documento gerado com um nome diferente do de costume sai assinado com o registro profissional certo daquela pessoa, não de outra. Preencha com cuidado.</div>\n\n    <h2 id=\"tplPgtPop_ms5\">5. Etapa 3 — POPs</h2>\n    <p>Marque, na lista, quais Procedimentos Operacionais Padrão você quer gerar pra esse hospital (lista de POPs já cadastrados, com nome de cada um). Se precisar de um POP que não está na lista, use <strong>\"+ Adicionar POP avulso\"</strong> pra criar um personalizado — dá pra remover qualquer um marcado por engano com o botão \"Remover\".</p>\n\n    <h2 id=\"tplPgtPop_ms6\">6. Etapa 4 — Gerar Documentos</h2>\n    <p>Clique em <strong>\"Gerar Tudo\"</strong>. O sistema gera o PGT (em 6 blocos de IA) e todos os POPs marcados, um por um. Isso pode levar alguns minutos — acompanhe pelo \"Histórico da operação\", visível em todas as etapas, que mostra o andamento. Ao terminar, clique em <strong>\"Ver Documentos\"</strong>.</p>\n\n    <h2 id=\"tplPgtPop_ms7\">7. Etapa 5 — Documentos Gerados</h2>\n    <table>\n      <tr><th>Botão</th><th>O que faz</th></tr>\n      <tr><td>Abrir</td><td>Abre aquele documento numa nova aba, pronto pra imprimir</td></tr>\n      <tr><td>Salvar no Drive</td><td>Salva uma cópia em PDF na pasta do hospital</td></tr>\n      <tr><td>Atualizar lista</td><td>Recarrega a lista, útil se você gerou mais documentos depois</td></tr>\n    </table>\n\n    <h2 id=\"tplPgtPop_ms8\">8. Passo a passo completo</h2>\n    <ol>\n      <li>Etapa 1: CNPJ, buscar, preencher porte/leitos/responsável técnico.</li>\n      <li>Etapa 2: preencher quem elaborou (nome/cargo/registro), roteiro e imagens do PGT.</li>\n      <li>Etapa 3: marcar os POPs desejados (ou adicionar avulso).</li>\n      <li>Etapa 4: clicar em \"Gerar Tudo\" e acompanhar o log até terminar.</li>\n      <li>Etapa 5: abrir cada documento, salvar no Drive.</li>\n    </ol>\n\n    <h2 id=\"tplPgtPop_ms9\">9. Erros comuns e o que fazer</h2>\n    <table>\n      <tr><th>O que aconteceu</th><th>O que fazer</th></tr>\n      <tr><td>A geração está demorando muito</td><td>Normal — o PGT sozinho já são 6 chamadas de IA em sequência; acompanhe o log, não feche a aba</td></tr>\n      <tr><td>Quero reaproveitar um documento já gerado pra esse hospital</td><td>Use \"Consultar documentos já gerados\" na etapa 1 antes de gerar de novo</td></tr>\n      <tr><td>Um POP que eu preciso não está na lista</td><td>Use \"+ Adicionar POP avulso\" na etapa 3</td></tr>\n    </table>\n\n    <h2 id=\"tplPgtPop_ms10\">10. Glossário</h2>\n    <table>\n      <tr><th>Termo</th><th>Explicação simples</th></tr>\n      <tr><td>PGT</td><td>Plano de Gerenciamento de Tecnologias em Saúde — documento amplo, exigido por norma, sobre a gestão dos equipamentos do hospital</td></tr>\n      <tr><td>POP</td><td>Procedimento Operacional Padrão — instrução passo a passo de como um processo específico deve ser feito</td></tr>\n      <tr><td>RDC nº 509/2021</td><td>Norma da ANVISA que embasa a exigência do PGT</td></tr>\n      <tr><td>POP avulso</td><td>Um POP personalizado, criado na hora, que não está na lista padrão do sistema</td></tr>\n    </table>\n\n    <a class=\"topo-link\" onclick=\"tplPgtPop_irParaSecao_('tplPgtPop_topoManual')\">↑ Topo</a>\n  </div>\n  </div>\n  `;\n\n  function tplPgtPop_abrirManual_() {\n    const viewModulo = document.getElementById('tplPgtPop_viewModulo');\n    const viewManual = document.getElementById('tplPgtPop_viewManual');\n    if (viewModulo) viewModulo.style.display = 'none';\n    if (viewManual) viewManual.style.display = '';\n  }\n\n  function tplPgtPop_voltarDoManual_() {\n    const viewModulo = document.getElementById('tplPgtPop_viewModulo');\n    const viewManual = document.getElementById('tplPgtPop_viewManual');\n    if (viewManual) viewManual.style.display = 'none';\n    if (viewModulo) viewModulo.style.display = '';\n  }\n\n  function tplPgtPop_irParaSecao_(id) {\n    const el = document.getElementById(id);\n    if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'start' });\n  }\n\n  // ============================================================\n  // ESTADO\n  // ============================================================\n  let tplPgtPop_bootstrap_ = null;\n  let tplPgtPop_estadoCatalogo_ = {}; // { codigo: { selecionado: bool, roteiro: string, imagens: [] } }\n  let tplPgtPop_popsAvulsos_ = []; // [{ id, nome, roteiro, imagens: [] }]\n  let tplPgtPop_imagensPgt_ = []; // [{ base64, mimeType, legenda }]\n  let tplPgtPop_documentosGerados_ = []; // resultados de PgtPop_apiGerarDocumento\n\n  function tplPgtPop_el(id) { return document.getElementById(id); }\n\n  function tplPgtPop_dispatch_(fn, payload) {\n    return new Promise((resolve, reject) => {\n      SGO_iniciarCarregamento_();\n      google.script.run\n        .withSuccessHandler(function(res) { SGO_finalizarCarregamento_(); resolve(res); })\n        .withFailureHandler(function(err) { SGO_finalizarCarregamento_(); reject(err); })\n        .PgtPop_apiDispatch({ sessionId: SGO_getSessionId(), fn: fn, payload: payload || {} });\n    });\n  }\n\n  function tplPgtPop_escapeHtml_(v) {\n    return String(v == null ? '' : v)\n      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')\n      .replace(/\"/g, '&quot;').replace(/'/g, '&#39;');\n  }\n\n  /** A coluna DATA volta como objeto Date (ou string ISO) — formata pt-BR pra não mostrar timestamp cru na tela. */\n  function tplPgtPop_formatarDataDoc_(v) {\n    if (!v) return '';\n    try {\n      const d = (v instanceof Date) ? v : new Date(v);\n      if (isNaN(d.getTime())) return String(v);\n      return d.toLocaleDateString('pt-BR');\n    } catch (e) {\n      return String(v);\n    }\n  }\n\n  function tplPgtPop_gerarIdLocal_() {\n    return 'av_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);\n  }\n\n  // ============================================================\n  // NAVEGAÇÃO\n  // ============================================================\n  function tplPgtPop_irParaEtapa(n) {\n    for (let i = 1; i <= 5; i++) {\n      const step = tplPgtPop_el('tplPgtPop_step' + i);\n      const nav = tplPgtPop_el('tplPgtPop_nav' + i);\n      if (step) step.classList.toggle('active', i === n);\n      if (nav) {\n        nav.classList.toggle('active', i === n);\n        nav.classList.toggle('done', i < n);\n      }\n    }\n    if (n === 5) tplPgtPop_carregarListaControle_();\n  }\n\n  // ============================================================\n  // INICIALIZAÇÃO\n  // ============================================================\n  function tplPgtPop_inicializar() {\n    \n    SGO_iniciarCarregamento_();\n    google.script.run\n      .withSuccessHandler(function (boot) {\n        SGO_finalizarCarregamento_();\n        if (!boot) {\n          tplPgtPop_writeLog('Conexão inicial não retornou dados (resposta vazia). Recarregue a página.', 'ERRO');\n          return;\n        }\n        tplPgtPop_bootstrap_ = boot;\n        const titulo = tplPgtPop_el('tplPgtPop_appTitulo');\n        if (titulo && boot.appNome) titulo.textContent = String(boot.appNome).replace(/^METROLABS\\s*[•-]\\s*/i, '');\n        const campoElaborado = tplPgtPop_el('tplPgtPop_elaboradoPorNome');\n        if (campoElaborado && boot.elaboradoPorNomePadrao) campoElaborado.value = boot.elaboradoPorNomePadrao;\n        const campoElaboradoCargo = tplPgtPop_el('tplPgtPop_elaboradoPorCargo');\n        if (campoElaboradoCargo && boot.elaboradoPorCargoPadrao) campoElaboradoCargo.value = boot.elaboradoPorCargoPadrao;\n        const campoElaboradoRegistro = tplPgtPop_el('tplPgtPop_elaboradoPorRegistro');\n        if (campoElaboradoRegistro && boot.elaboradoPorRegistroPadrao) campoElaboradoRegistro.value = boot.elaboradoPorRegistroPadrao;\n        tplPgtPop_renderCatalogoPops();\n        \n      })\n      .withFailureHandler(function (err) {\n        SGO_finalizarCarregamento_();\n        console.error('tplPgtPop_inicializar falhou:', err);\n        tplPgtPop_writeLog('Não foi possível carregar a configuração: ' + (err && err.message ? err.message : err) + '. Recarregue a página (F5).', 'ERRO');\n      })\n      .PgtPop_getAppBootstrap();\n  }\n\n  // ============================================================\n  // UPLOAD DE IMAGENS (compartilhado entre PGT / catálogo / avulsos)\n  // ============================================================\n  function tplPgtPop_lerArquivosComoImagens_(fileList) {\n    const arquivos = Array.from(fileList || []);\n    return Promise.all(arquivos.map(arquivo => new Promise((resolve, reject) => {\n      const reader = new FileReader();\n      reader.onload = () => {\n        const resultado = String(reader.result || '');\n        const base64 = resultado.split(',')[1] || '';\n        resolve({ base64: base64, mimeType: arquivo.type || 'image/jpeg', legenda: '' });\n      };\n      reader.onerror = reject;\n      reader.readAsDataURL(arquivo);\n    })));\n  }\n\n  // fnAtualizarLegenda/fnRemover: NOME (string) de uma função global com\n  // assinatura (...argsExtras, i, valor) / (...argsExtras, i). argsExtrasStr\n  // já vem pronto pra ser colado literalmente antes de \"i\" na chamada (ex.:\n  // \"'POP001', \" ou \"3, \" ou \"\" quando não há contexto extra).\n  function tplPgtPop_renderImgSlots_(imagens, fnAtualizarLegenda, fnRemover, argsExtrasStr) {\n    argsExtrasStr = argsExtrasStr || '';\n    if (!imagens.length) return '<div style=\"color: var(--muted); font-size: 11px; margin-top: 6px;\">Nenhuma imagem anexada.</div>';\n    return '<div class=\"img-slot-list\">' + imagens.map((img, i) => `\n      <div class=\"img-slot\">\n        <img src=\"data:${img.mimeType};base64,${img.base64}\" alt=\"Imagem ${i + 1}\">\n        <input type=\"text\" placeholder=\"Legenda\" value=\"${tplPgtPop_escapeHtml_(img.legenda)}\" onchange=\"${fnAtualizarLegenda}(${argsExtrasStr}${i}, this.value)\">\n        <button type=\"button\" class=\"btn btn-danger btn-xs\" onclick=\"${fnRemover}(${argsExtrasStr}${i})\">Remover</button>\n      </div>\n    `).join('') + '</div>';\n  }\n\n  // --- PGT ---\n  async function tplPgtPop_addImagensPgt_(input) {\n    const novas = await tplPgtPop_lerArquivosComoImagens_(input.files);\n    tplPgtPop_imagensPgt_ = tplPgtPop_imagensPgt_.concat(novas);\n    input.value = '';\n    tplPgtPop_renderImagensPgt_();\n  }\n  function tplPgtPop_atualizarLegendaPgt_(i, valor) { tplPgtPop_imagensPgt_[i].legenda = valor; }\n  function tplPgtPop_removerImagemPgt_(i) { tplPgtPop_imagensPgt_.splice(i, 1); tplPgtPop_renderImagensPgt_(); }\n  function tplPgtPop_renderImagensPgt_() {\n    const div = tplPgtPop_el('tplPgtPop_imagensPgtWrap');\n    if (div) div.innerHTML = tplPgtPop_renderImgSlots_(tplPgtPop_imagensPgt_, 'tplPgtPop_atualizarLegendaPgt_', 'tplPgtPop_removerImagemPgt_', '');\n  }\n\n  // ============================================================\n  // PASSO 1 — CNPJ\n  // ============================================================\n  async function tplPgtPop_buscarCNPJ() {\n    const cnpj = tplPgtPop_el('tplPgtPop_cnpj').value;\n    const alerta = tplPgtPop_el('tplPgtPop_alertaCnpj');\n    const btn = tplPgtPop_el('tplPgtPop_btnBuscarCnpj');\n    alerta.innerHTML = '';\n    btn.disabled = true;\n    btn.textContent = 'Buscando...';\n    tplPgtPop_writeLog('Consultando CNPJ ' + cnpj + ' em base pública...');\n    try {\n      const r = tplPgtPop_verificarResposta_(await tplPgtPop_dispatch_('apiConsultarCnpj', { cnpj: cnpj }), 'buscar CNPJ');\n      tplPgtPop_el('tplPgtPop_cnpj').value = r.cnpj || cnpj;\n      tplPgtPop_el('tplPgtPop_hospital').value = r.razaoSocial || r.cliente || '';\n      tplPgtPop_el('tplPgtPop_logradouro').value = r.logradouro || '';\n      tplPgtPop_el('tplPgtPop_bairro').value = r.bairro || '';\n      tplPgtPop_el('tplPgtPop_cidade').value = r.municipio || '';\n      tplPgtPop_el('tplPgtPop_uf').value = r.uf || '';\n      alerta.innerHTML = '<div class=\"alert-box success\">CNPJ encontrado (' + tplPgtPop_escapeHtml_(r.fonte || '') + ').</div>';\n      tplPgtPop_writeLog('CNPJ encontrado: ' + (r.razaoSocial || r.cliente || '-'), 'SUCESSO');\n    } catch (e) {\n      const msgCnpj = String(e && e.message ? e.message : e).replace(/^Error:\\s*/i, '').trim();\n      alerta.innerHTML = '<div class=\"alert-box warning\">Não foi possível buscar automaticamente: ' + tplPgtPop_escapeHtml_(msgCnpj) + (/preencha manualmente/i.test(msgCnpj) ? '' : (/[.!?]$/.test(msgCnpj) ? ' ' : '. ') + 'Preencha manualmente.') + '</div>';\n      tplPgtPop_writeLog('Falha ao buscar CNPJ: ' + (e && e.message ? e.message : e), 'ERRO');\n    } finally {\n      btn.disabled = false;\n      btn.textContent = 'Buscar';\n    }\n  }\n\n  function tplPgtPop_obterHospital_() {\n    return {\n      cnpj: tplPgtPop_el('tplPgtPop_cnpj').value,\n      razaoSocial: tplPgtPop_el('tplPgtPop_hospital').value,\n      logradouro: tplPgtPop_el('tplPgtPop_logradouro').value,\n      bairro: tplPgtPop_el('tplPgtPop_bairro').value,\n      cidade: tplPgtPop_el('tplPgtPop_cidade').value,\n      uf: tplPgtPop_el('tplPgtPop_uf').value,\n      porte: tplPgtPop_el('tplPgtPop_porte').value,\n      leitos: tplPgtPop_el('tplPgtPop_leitos').value,\n      aprovadorNome: tplPgtPop_el('tplPgtPop_aprovadorNome').value,\n      aprovadorCargo: tplPgtPop_el('tplPgtPop_aprovadorCargo').value\n    };\n  }\n\n  function tplPgtPop_obterElaboradoPorNome_() {\n    return tplPgtPop_el('tplPgtPop_elaboradoPorNome').value || (tplPgtPop_bootstrap_ && tplPgtPop_bootstrap_.elaboradoPorNomePadrao) || '';\n  }\n\n  function tplPgtPop_obterElaboradoPorCargo_() {\n    return tplPgtPop_el('tplPgtPop_elaboradoPorCargo').value || (tplPgtPop_bootstrap_ && tplPgtPop_bootstrap_.elaboradoPorCargoPadrao) || '';\n  }\n\n  function tplPgtPop_obterElaboradoPorRegistro_() {\n    return tplPgtPop_el('tplPgtPop_elaboradoPorRegistro').value || (tplPgtPop_bootstrap_ && tplPgtPop_bootstrap_.elaboradoPorRegistroPadrao) || '';\n  }\n\n  // ============================================================\n  // CONSULTAR DOCUMENTOS JÁ EXISTENTES (por CNPJ)\n  // ============================================================\n  async function tplPgtPop_consultarDocumentosExistentes_() {\n    const cnpj = tplPgtPop_el('tplPgtPop_cnpj').value;\n    const wrap = tplPgtPop_el('tplPgtPop_docsExistentesWrap');\n    const btn = tplPgtPop_el('tplPgtPop_btnConsultarDocs');\n    if (!cnpj.trim()) {\n      wrap.innerHTML = '<div class=\"alert-box warning\">Informe o CNPJ antes de consultar.</div>';\n      return;\n    }\n    btn.disabled = true;\n    btn.textContent = 'Consultando...';\n    wrap.innerHTML = '';\n    tplPgtPop_writeLog('Consultando documentos já gerados para o CNPJ ' + cnpj + '...');\n    // 2026-08-14 (v14) — troca de método a pedido do usuário: em vez de\n    // reconstruir cada documento sob demanda (fluxo antigo, frágil —\n    // vários bugs reais de serialização), a partir de agora todo\n    // documento gerado já salva o PDF automaticamente numa pasta do\n    // Drive por CNPJ. \"Consultar documentos já gerados\" agora é\n    // literalmente listar os arquivos dessa pasta — link direto pro\n    // PDF, sem nenhuma reconstrução via servidor.\n    try {\n      const rArquivos = tplPgtPop_verificarResposta_(await tplPgtPop_dispatch_('apiListarArquivosPdf', { cnpj: cnpj }), 'consultar documentos já gerados');\n      if (!rArquivos.ok) {\n        wrap.innerHTML = '<div class=\"alert-box error\">' + tplPgtPop_escapeHtml_(rArquivos.mensagem) + '</div>';\n        tplPgtPop_writeLog('Consulta falhou: ' + rArquivos.mensagem, 'ERRO');\n        return;\n      }\n      if (!rArquivos.arquivos.length) {\n        wrap.innerHTML = '<div class=\"alert-box info\">Nenhum documento encontrado pra este CNPJ ainda — pode gerar do zero normalmente.</div>';\n        tplPgtPop_writeLog('Nenhum documento encontrado pra este CNPJ.');\n      } else {\n        wrap.innerHTML = '<div class=\"alert-box success\">' + rArquivos.arquivos.length + ' documento(s) já existente(s) encontrado(s) pra este CNPJ:</div>' +\n          rArquivos.arquivos.map(a => `\n            <div class=\"doc-item\">\n              <div class=\"doc-titulo\">${tplPgtPop_escapeHtml_(a.nome)} <span style=\"color:var(--muted);font-weight:400;\">(${tplPgtPop_escapeHtml_(a.data)})</span></div>\n              <a class=\"btn btn-secondary\" href=\"${a.url}\" target=\"_blank\" rel=\"noopener\">Abrir PDF</a>\n            </div>\n          `).join('');\n        tplPgtPop_writeLog(rArquivos.arquivos.length + ' documento(s) encontrado(s) pra este CNPJ.', 'SUCESSO');\n      }\n\n      // Pré-preenche os dados do hospital com o que já está salvo, se o\n      // usuário só digitou o CNPJ e ainda não preencheu o resto — usa\n      // apiListarDocumentos só pra isso agora (não mais pra montar a\n      // lista visível de documentos).\n      const rDados = tplPgtPop_verificarResposta_(await tplPgtPop_dispatch_('apiListarDocumentos', { cnpj: cnpj }), 'carregar dados do hospital');\n      if (rDados.ok) {\n        const documentos = JSON.parse(rDados.documentosJson || '[]');\n        const primeiro = documentos[0];\n        if (primeiro && primeiro.hospital && primeiro.hospital.razaoSocial && !tplPgtPop_el('tplPgtPop_hospital').value) {\n          tplPgtPop_el('tplPgtPop_hospital').value = primeiro.hospital.razaoSocial || '';\n          tplPgtPop_el('tplPgtPop_logradouro').value = primeiro.hospital.logradouro || '';\n          tplPgtPop_el('tplPgtPop_bairro').value = primeiro.hospital.bairro || '';\n          tplPgtPop_el('tplPgtPop_cidade').value = primeiro.hospital.cidade || '';\n          tplPgtPop_el('tplPgtPop_uf').value = primeiro.hospital.uf || '';\n          tplPgtPop_el('tplPgtPop_porte').value = primeiro.hospital.porte || '';\n          tplPgtPop_el('tplPgtPop_leitos').value = primeiro.hospital.leitos || '';\n          tplPgtPop_el('tplPgtPop_aprovadorNome').value = primeiro.hospital.aprovadorNome || '';\n          tplPgtPop_el('tplPgtPop_aprovadorCargo').value = primeiro.hospital.aprovadorCargo || '';\n        }\n      }\n    } catch (e) {\n      const msg = (e && e.message ? e.message : e);\n      wrap.innerHTML = '<div class=\"alert-box error\">Erro ao consultar: ' + tplPgtPop_escapeHtml_(msg) + '</div>';\n      tplPgtPop_writeLog('Erro ao consultar documentos: ' + msg, 'ERRO');\n    } finally {\n      btn.disabled = false;\n      btn.textContent = 'Consultar documentos já gerados';\n    }\n  }\n\n  // ============================================================\n  // PASSO 3 — POPS\n  // ============================================================\n  function tplPgtPop_renderCatalogoPops() {\n    const div = tplPgtPop_el('tplPgtPop_catalogoPops');\n    const catalogo = (tplPgtPop_bootstrap_ && tplPgtPop_bootstrap_.catalogoPops) || [];\n    catalogo.forEach(p => {\n      if (!tplPgtPop_estadoCatalogo_[p.codigo]) tplPgtPop_estadoCatalogo_[p.codigo] = { selecionado: false, roteiro: '', imagens: [] };\n    });\n    div.innerHTML = catalogo.map(p => `\n      <div class=\"pop-card\">\n        <div class=\"pop-card-head\">\n          <input type=\"checkbox\" id=\"tplPgtPop_chk_${p.codigo}\" onchange=\"tplPgtPop_togglePop_('${p.codigo}', this.checked)\">\n          <span class=\"pop-card-codigo\">${p.codigo}</span>\n          <label for=\"tplPgtPop_chk_${p.codigo}\">${tplPgtPop_escapeHtml_(p.nome)}</label>\n        </div>\n        <div class=\"pop-card-extra hidden\" id=\"tplPgtPop_extra_${p.codigo}\">\n          <textarea class=\"form-control\" placeholder=\"Roteiro opcional pra este POP...\" onchange=\"tplPgtPop_atualizarRoteiroPop_('${p.codigo}', this.value)\"></textarea>\n          <input type=\"file\" accept=\"image/*\" multiple onchange=\"tplPgtPop_addImagensCatalogo_('${p.codigo}', this)\" style=\"margin-top:8px;\">\n          <div id=\"tplPgtPop_imgs_${p.codigo}\"></div>\n        </div>\n      </div>\n    `).join('');\n  }\n\n  function tplPgtPop_togglePop_(codigo, checked) {\n    if (!tplPgtPop_estadoCatalogo_[codigo]) tplPgtPop_estadoCatalogo_[codigo] = { selecionado: false, roteiro: '', imagens: [] };\n    tplPgtPop_estadoCatalogo_[codigo].selecionado = checked;\n    const wrap = tplPgtPop_el('tplPgtPop_extra_' + codigo);\n    if (wrap) wrap.classList.toggle('hidden', !checked);\n  }\n\n  function tplPgtPop_atualizarRoteiroPop_(codigo, valor) {\n    if (!tplPgtPop_estadoCatalogo_[codigo]) tplPgtPop_estadoCatalogo_[codigo] = { selecionado: false, roteiro: '', imagens: [] };\n    tplPgtPop_estadoCatalogo_[codigo].roteiro = valor;\n  }\n\n  async function tplPgtPop_addImagensCatalogo_(codigo, input) {\n    const novas = await tplPgtPop_lerArquivosComoImagens_(input.files);\n    tplPgtPop_estadoCatalogo_[codigo].imagens = (tplPgtPop_estadoCatalogo_[codigo].imagens || []).concat(novas);\n    input.value = '';\n    tplPgtPop_renderImagensCatalogo_(codigo);\n  }\n  function tplPgtPop_atualizarLegendaCatalogo_(codigo, i, valor) { tplPgtPop_estadoCatalogo_[codigo].imagens[i].legenda = valor; }\n  function tplPgtPop_removerImagemCatalogo_(codigo, i) {\n    tplPgtPop_estadoCatalogo_[codigo].imagens.splice(i, 1);\n    tplPgtPop_renderImagensCatalogo_(codigo);\n  }\n  function tplPgtPop_renderImagensCatalogo_(codigo) {\n    const div = tplPgtPop_el('tplPgtPop_imgs_' + codigo);\n    if (!div) return;\n    const imagens = tplPgtPop_estadoCatalogo_[codigo].imagens || [];\n    div.innerHTML = tplPgtPop_renderImgSlots_(\n      imagens,\n      'tplPgtPop_atualizarLegendaCatalogo_',\n      'tplPgtPop_removerImagemCatalogo_',\n      \"'\" + codigo + \"', \"\n    );\n  }\n\n  function tplPgtPop_addPopAvulso() {\n    const nome = tplPgtPop_el('tplPgtPop_avulsoNome').value.trim();\n    if (!nome) { alert('Informe o nome do POP.'); return; }\n    tplPgtPop_popsAvulsos_.push({ id: tplPgtPop_gerarIdLocal_(), nome: nome, roteiro: '', imagens: [] });\n    tplPgtPop_el('tplPgtPop_avulsoNome').value = '';\n    tplPgtPop_renderPopsAvulsos_();\n  }\n\n  function tplPgtPop_removerPopAvulso_(idx) {\n    tplPgtPop_popsAvulsos_.splice(idx, 1);\n    tplPgtPop_renderPopsAvulsos_();\n  }\n\n  function tplPgtPop_atualizarRoteiroAvulso_(idx, valor) {\n    tplPgtPop_popsAvulsos_[idx].roteiro = valor;\n  }\n\n  async function tplPgtPop_addImagensAvulso_(idx, input) {\n    const novas = await tplPgtPop_lerArquivosComoImagens_(input.files);\n    tplPgtPop_popsAvulsos_[idx].imagens = (tplPgtPop_popsAvulsos_[idx].imagens || []).concat(novas);\n    input.value = '';\n    tplPgtPop_renderPopsAvulsos_();\n  }\n  function tplPgtPop_atualizarLegendaAvulso_(idx, i, valor) { tplPgtPop_popsAvulsos_[idx].imagens[i].legenda = valor; }\n  function tplPgtPop_removerImagemAvulso_(idx, i) { tplPgtPop_popsAvulsos_[idx].imagens.splice(i, 1); tplPgtPop_renderPopsAvulsos_(); }\n\n  function tplPgtPop_renderPopsAvulsos_() {\n    const div = tplPgtPop_el('tplPgtPop_listaAvulsos');\n    if (!tplPgtPop_popsAvulsos_.length) { div.innerHTML = ''; return; }\n    div.innerHTML = tplPgtPop_popsAvulsos_.map((p, i) => `\n      <div class=\"pop-avulso-item\">\n        <div class=\"avulso-nome\">${tplPgtPop_escapeHtml_(p.nome)}</div>\n        <button type=\"button\" class=\"btn btn-danger btn-xs\" onclick=\"tplPgtPop_removerPopAvulso_(${i})\">Remover</button>\n      </div>\n      <div class=\"pop-card-extra\" style=\"margin-left:0;margin-bottom:8px;\">\n        <textarea class=\"form-control\" placeholder=\"Roteiro opcional pra este POP...\" onchange=\"tplPgtPop_atualizarRoteiroAvulso_(${i}, this.value)\">${tplPgtPop_escapeHtml_(p.roteiro)}</textarea>\n        <input type=\"file\" accept=\"image/*\" multiple onchange=\"tplPgtPop_addImagensAvulso_(${i}, this)\" style=\"margin-top:8px;\">\n        ${tplPgtPop_renderImgSlots_(p.imagens || [], 'tplPgtPop_atualizarLegendaAvulso_', 'tplPgtPop_removerImagemAvulso_', i + \", \")}\n      </div>\n    `).join('');\n  }\n\n  function tplPgtPop_coletarPopsSelecionados_() {\n    const catalogo = (tplPgtPop_bootstrap_ && tplPgtPop_bootstrap_.catalogoPops) || [];\n    const selecionados = catalogo\n      .filter(p => tplPgtPop_estadoCatalogo_[p.codigo] && tplPgtPop_estadoCatalogo_[p.codigo].selecionado)\n      .map(p => ({ codigo: p.codigo, nome: p.nome, roteiro: tplPgtPop_estadoCatalogo_[p.codigo].roteiro || '', imagens: tplPgtPop_estadoCatalogo_[p.codigo].imagens || [] }));\n    const avulsos = tplPgtPop_popsAvulsos_.map(p => ({ codigo: '', nome: p.nome, roteiro: p.roteiro || '', imagens: p.imagens || [] }));\n    return selecionados.concat(avulsos);\n  }\n\n  // ============================================================\n  // CONSOLE OPERACIONAL (visível em todas as etapas, 2026-08-14 —\n  // pedido do usuário depois de um bug real que só dava pra diagnosticar\n  // rodando código direto no servidor; agora toda ação relevante fica\n  // registrada na tela, pro usuário conseguir descrever/printar o que\n  // aconteceu de verdade, sem depender de mensagem de erro técnica)\n  // ============================================================\n  function tplPgtPop_writeLog(msg, tipo) {\n    const term = tplPgtPop_el('tplPgtPop_terminalLog');\n    if (!term) return;\n    const cls = tipo === 'ERRO' ? 'erro' : (tipo === 'AVISO' ? 'aviso' : '');\n    const linha = document.createElement('div');\n    if (cls) linha.className = cls;\n    linha.textContent = '[' + new Date().toLocaleTimeString() + '] ' + msg;\n    term.appendChild(linha);\n    term.scrollTop = term.scrollHeight;\n  }\n\n  function tplPgtPop_limparLog() {\n    const term = tplPgtPop_el('tplPgtPop_terminalLog');\n    if (term) term.innerHTML = '';\n    tplPgtPop_writeLog('Log limpo. Aguardando novas operações...');\n  }\n\n  /**\n   * Toda resposta de google.script.run passa por aqui antes de ler\n   * `.ok`. Existe pra cobrir o caso real (2026-08-14) em que o servidor\n   * devolve uma resposta grande demais pro canal do Apps Script e o\n   * navegador recebe `null` silenciosamente, sem erro nenhum — sem essa\n   * checagem, o próximo código quebrava com \"Cannot read properties of\n   * null\", uma mensagem que só faz sentido pra quem programou.\n   */\n  function tplPgtPop_verificarResposta_(r, contexto) {\n    if (!r) {\n      const msg = 'O servidor não respondeu à operação \"' + contexto + '\" (resposta vazia/nula). Costuma acontecer quando a resposta é grande demais ou a sessão da página está desatualizada. Recarregue a página (F5) e tente de novo — se persistir, avise o suporte com o horário e os dados usados.';\n      tplPgtPop_writeLog(msg, 'ERRO');\n      throw new Error(msg);\n    }\n    return r;\n  }\n\n  async function tplPgtPop_gerarTudo() {\n    const hospital = tplPgtPop_obterHospital_();\n    if (!hospital.razaoSocial) {\n      tplPgtPop_writeLog('Informe os dados do hospital na etapa 1 antes de gerar.', 'ERRO');\n      return;\n    }\n    const pops = tplPgtPop_coletarPopsSelecionados_();\n    const roteiroPgt = tplPgtPop_el('tplPgtPop_roteiroPgt').value;\n    const elaboradoPorNome = tplPgtPop_obterElaboradoPorNome_();\n    const elaboradoPorCargo = tplPgtPop_obterElaboradoPorCargo_();\n    const elaboradoPorRegistro = tplPgtPop_obterElaboradoPorRegistro_();\n\n    const btn = tplPgtPop_el('tplPgtPop_btnGerar');\n    btn.disabled = true;\n    tplPgtPop_documentosGerados_ = [];\n    // Log agora é um console persistente (visível em todas as etapas) —\n    // não limpa mais sozinho a cada geração, só via botão \"Limpar log\".\n    tplPgtPop_writeLog('Iniciando geração — 1 PGT + ' + pops.length + ' POP(s).');\n\n    let pgtId = '';\n    try {\n      // PGT agora é gerado em 6 blocos (2026-08-14, documento muito mais\n      // robusto/detalhado) — leva bem mais tempo que antes, avisa o\n      // usuário pra não parecer travado.\n      tplPgtPop_writeLog('Gerando PGT (documento em 6 partes — Escopo/Termos, Requisitos Gerais, 3 blocos de Requisitos Específicos, Fechamento — pode levar alguns minutos)...');\n      const popsRelacionados = pops.map(p => ({ codigo: p.codigo, nome: p.nome }));\n      const rPgt = tplPgtPop_verificarResposta_(await tplPgtPop_dispatch_('apiGerarDocumento', { tipo: 'PGT', hospital: hospital, roteiro: roteiroPgt, imagens: tplPgtPop_imagensPgt_, popsRelacionados: popsRelacionados, elaboradoPorNome: elaboradoPorNome, elaboradoPorCargo: elaboradoPorCargo, elaboradoPorRegistro: elaboradoPorRegistro }), 'gerar PGT');\n      if (!rPgt.ok) {\n        tplPgtPop_writeLog('Falha no PGT: ' + rPgt.mensagem, 'ERRO');\n      } else {\n        pgtId = rPgt.registroId;\n        tplPgtPop_documentosGerados_.push(rPgt);\n        tplPgtPop_writeLog('PGT gerado (revisão ' + rPgt.versaoAtual + '.0): \"' + rPgt.titulo + '\".');\n      }\n    } catch (e) {\n      tplPgtPop_writeLog('Erro ao gerar o PGT: ' + (e && e.message ? e.message : e), 'ERRO');\n    }\n\n    for (let i = 0; i < pops.length; i++) {\n      const pop = pops[i];\n      tplPgtPop_writeLog('Gerando POP ' + (i + 1) + '/' + pops.length + ': ' + pop.nome + (pop.imagens.length ? (' (' + pop.imagens.length + ' imagem(ns))') : '') + '...');\n      try {\n        const rPop = tplPgtPop_verificarResposta_(await tplPgtPop_dispatch_('apiGerarDocumento', {\n          tipo: 'POP', hospital: hospital, roteiro: pop.roteiro,\n          pop: { codigo: pop.codigo, nome: pop.nome }, pgtId: pgtId, imagens: pop.imagens,\n          elaboradoPorNome: elaboradoPorNome, elaboradoPorCargo: elaboradoPorCargo, elaboradoPorRegistro: elaboradoPorRegistro\n        }), 'gerar POP \"' + pop.nome + '\"');\n        if (!rPop.ok) {\n          tplPgtPop_writeLog('Falha no POP \"' + pop.nome + '\": ' + rPop.mensagem, 'ERRO');\n        } else {\n          tplPgtPop_documentosGerados_.push(rPop);\n          tplPgtPop_writeLog('POP gerado (revisão ' + rPop.versaoAtual + '.0): \"' + rPop.titulo + '\".');\n        }\n      } catch (e) {\n        tplPgtPop_writeLog('Erro ao gerar o POP \"' + pop.nome + '\": ' + (e && e.message ? e.message : e), 'ERRO');\n      }\n    }\n\n    tplPgtPop_writeLog('Concluído. ' + tplPgtPop_documentosGerados_.length + ' documento(s) gerado(s) com sucesso.');\n    btn.disabled = false;\n    tplPgtPop_renderListaDocumentos_();\n    tplPgtPop_irParaEtapa(5);\n  }\n\n  // ============================================================\n  // PASSO 5 — DOCUMENTOS\n  // ============================================================\n  function tplPgtPop_renderListaDocumentos_() {\n    const div = tplPgtPop_el('tplPgtPop_listaDocumentos');\n    if (!tplPgtPop_documentosGerados_.length) {\n      div.innerHTML = '<div style=\"color: var(--muted); font-size: 12px;\">Nenhum documento gerado ainda.</div>';\n      return;\n    }\n    div.innerHTML = tplPgtPop_documentosGerados_.map((d, i) => `\n      <div class=\"doc-item\">\n        <span class=\"doc-tipo ${d.tipo === 'POP' ? 'pop' : ''}\">${d.tipo}</span>\n        <div class=\"doc-titulo\">${tplPgtPop_escapeHtml_(d.titulo)} <span style=\"color:var(--muted);font-weight:400;\">(rev. ${d.versaoAtual}.0)</span></div>\n        <button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplPgtPop_abrirDocumento_(${i})\">Abrir</button>\n        ${d.pdfUrl ? `<a class=\"btn btn-secondary\" href=\"${d.pdfUrl}\" target=\"_blank\" rel=\"noopener\">PDF salvo</a>` : `<button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplPgtPop_salvarDocumento_(${i})\">Salvar no Drive</button>`}\n        <span id=\"tplPgtPop_statusDoc_${i}\"></span>\n      </div>\n    `).join('');\n  }\n\n  async function tplPgtPop_abrirDocumento_(idx) {\n    let doc = tplPgtPop_documentosGerados_[idx];\n    const status = tplPgtPop_el('tplPgtPop_statusDoc_' + idx);\n    // Bugfix 2026-08-14: (1) a lista de \"documentos já gerados\" (consulta\n    // por CNPJ) nunca tinha o <span id=\"tplPgtPop_statusDoc_N\"> — essa\n    // linha lançava \"Cannot set properties of null\" ANTES do try/catch,\n    // o clique não fazia nada visível, nenhum log, nenhum erro. Agora\n    // `setStatus_` não quebra se o elemento não existir. (2) window.open()\n    // só era chamado depois de 2 `await` — a maioria dos navegadores trata\n    // isso como popup fora de uma interação direta do usuário e BLOQUEIA\n    // silenciosamente (sem erro no console, sem nada). Agora a aba é\n    // aberta em branco IMEDIATAMENTE (síncrono, direto no clique) e só\n    // recebe o conteúdo depois, quando fica pronto.\n    function setStatus_(txt) { if (status) status.textContent = txt; }\n\n    const win = window.open('', '_blank');\n    if (win) {\n      win.document.write('<p style=\"font-family:sans-serif;color:#555;padding:24px;\">Gerando documento, aguarde...</p>');\n    } else {\n      tplPgtPop_writeLog('O navegador bloqueou a abertura da nova aba (pop-up). Permita pop-ups pra este site e tente de novo.', 'AVISO');\n    }\n\n    setStatus_(' Montando...');\n    tplPgtPop_writeLog('Abrindo documento: ' + (doc.titulo || doc.codigoDocumento) + '...');\n    try {\n      // Documentos que vieram da consulta por CNPJ chegam \"leves\" (sem\n      // texto/imagens, pra não estourar o limite de payload do\n      // google.script.run) — busca o conteúdo completo sob demanda.\n      if (doc.textoGerado === undefined) {\n        setStatus_(' Carregando conteúdo completo...');\n        tplPgtPop_writeLog('Carregando conteúdo completo do documento...');\n        const respCompleto = tplPgtPop_verificarResposta_(await tplPgtPop_dispatch_('apiObterDocumentoPorId', { tipo: doc.tipo, registroId: doc.registroId }), 'carregar conteúdo do documento');\n        if (!respCompleto.ok) {\n          setStatus_(' Erro: ' + respCompleto.mensagem);\n          tplPgtPop_writeLog('Falha ao carregar conteúdo: ' + respCompleto.mensagem, 'ERRO');\n          if (win) win.document.write('<p style=\"font-family:sans-serif;color:#b91c1c;padding:24px;\">Erro: ' + tplPgtPop_escapeHtml_(respCompleto.mensagem) + '</p>');\n          return;\n        }\n        // documentoJson (string) em vez de objeto direto — mesma defesa\n        // usada em apiListarDocumentos, ver comentário no backend.\n        const completo = JSON.parse(respCompleto.documentoJson);\n        doc = Object.assign(doc, completo);\n        setStatus_(' Montando...');\n      }\n      const r = tplPgtPop_verificarResposta_(await tplPgtPop_dispatch_('apiMontarDocumentoFinal', doc), 'montar documento');\n      if (!r.ok) {\n        setStatus_(' Erro: ' + r.mensagem);\n        tplPgtPop_writeLog('Falha ao montar documento: ' + r.mensagem, 'ERRO');\n        if (win) win.document.write('<p style=\"font-family:sans-serif;color:#b91c1c;padding:24px;\">Erro: ' + tplPgtPop_escapeHtml_(r.mensagem) + '</p>');\n        return;\n      }\n      doc.htmlDocumento = r.html;\n      if (win) {\n        win.document.open();\n        win.document.write(r.html);\n        win.document.close();\n      }\n      setStatus_('');\n      tplPgtPop_writeLog('Documento aberto com sucesso.', 'SUCESSO');\n    } catch (e) {\n      const msg = (e && e.message ? e.message : e);\n      setStatus_(' Erro: ' + msg);\n      tplPgtPop_writeLog('Erro ao abrir documento: ' + msg, 'ERRO');\n      if (win) win.document.write('<p style=\"font-family:sans-serif;color:#b91c1c;padding:24px;\">Erro: ' + tplPgtPop_escapeHtml_(msg) + '</p>');\n    }\n  }\n\n  async function tplPgtPop_salvarDocumento_(idx) {\n    const doc = tplPgtPop_documentosGerados_[idx];\n    const status = tplPgtPop_el('tplPgtPop_statusDoc_' + idx);\n    function setStatus_(txt) { if (status) status.textContent = txt; }\n    if (!doc.htmlDocumento) {\n      setStatus_(' Abra o documento primeiro.');\n      tplPgtPop_writeLog('Tentativa de salvar sem abrir o documento antes.', 'AVISO');\n      return;\n    }\n    setStatus_(' Salvando...');\n    tplPgtPop_writeLog('Salvando documento no Drive: ' + (doc.titulo || doc.codigoDocumento) + '...');\n    try {\n      const r = tplPgtPop_verificarResposta_(await tplPgtPop_dispatch_('apiSalvarDocumento', {\n        html: doc.htmlDocumento,\n        hospital: (doc.hospital && doc.hospital.razaoSocial) || 'HOSPITAL',\n        cnpj: (doc.hospital && doc.hospital.cnpj) || '',\n        tipo: doc.tipo,\n        codigoDocumento: doc.codigoDocumento,\n        versaoAtual: doc.versaoAtual,\n        registroId: doc.registroId\n      }), 'salvar documento no Drive');\n      if (!r.ok) {\n        setStatus_(' Erro: ' + r.mensagem);\n        tplPgtPop_writeLog('Falha ao salvar no Drive: ' + r.mensagem, 'ERRO');\n        return;\n      }\n      if (status) status.innerHTML = ' <a href=\"' + r.url + '\" target=\"_blank\">Salvo</a>';\n      tplPgtPop_writeLog('Documento salvo no Drive: ' + r.fileName, 'SUCESSO');\n    } catch (e) {\n      const msg = (e && e.message ? e.message : e);\n      setStatus_(' Erro: ' + msg);\n      tplPgtPop_writeLog('Erro ao salvar no Drive: ' + msg, 'ERRO');\n    }\n  }\n\n  async function tplPgtPop_carregarListaControle_() {\n    // Bugfix 2026-08-14: mandava { hospital } mas a API espera { cnpj }, e\n    // lia campos (d.codigo/d.versao) que não existem na resposta real\n    // (d.codigoDocumento/d.versaoAtual) — nunca funcionou de verdade, só\n    // mostrava \"nenhum documento\" sempre, silenciosamente.\n    const cnpj = tplPgtPop_el('tplPgtPop_cnpj').value;\n    const div = tplPgtPop_el('tplPgtPop_listaControle');\n    if (!cnpj || !cnpj.trim()) { div.innerHTML = '<div style=\"color: var(--muted); font-size: 12px;\">Informe o CNPJ na etapa 1 pra ver a lista de controle.</div>'; return; }\n    div.innerHTML = '<div style=\"color: var(--muted); font-size: 12px;\">Carregando...</div>';\n    tplPgtPop_writeLog('Atualizando lista de controle de documentos...');\n    try {\n      const r = tplPgtPop_verificarResposta_(await tplPgtPop_dispatch_('apiListarDocumentos', { cnpj: cnpj }), 'atualizar lista de controle');\n      const documentos = r.ok ? JSON.parse(r.documentosJson || '[]') : [];\n      if (!r.ok || !documentos.length) {\n        div.innerHTML = '<div style=\"color: var(--muted); font-size: 12px;\">Nenhum documento registrado ainda pra este CNPJ.</div>';\n        tplPgtPop_writeLog(r.ok ? 'Lista de controle vazia pra este CNPJ.' : ('Falha ao atualizar lista: ' + r.mensagem), r.ok ? undefined : 'ERRO');\n        return;\n      }\n      div.innerHTML = '<table class=\"lista-doc\"><thead><tr><th>Código</th><th>Título</th><th>Revisão</th><th>Data</th></tr></thead><tbody>' +\n        documentos.map(d => `<tr><td>${tplPgtPop_escapeHtml_(d.codigoDocumento)}</td><td>${tplPgtPop_escapeHtml_(d.titulo)}</td><td>${d.versaoAtual}.0</td><td>${tplPgtPop_escapeHtml_(tplPgtPop_formatarDataDoc_(d.data))}</td></tr>`).join('') +\n        '</tbody></table>';\n      tplPgtPop_writeLog('Lista de controle atualizada: ' + documentos.length + ' documento(s).', 'SUCESSO');\n    } catch (e) {\n      const msg = (e && e.message ? e.message : e);\n      div.innerHTML = '<div class=\"alert-box error\">Erro ao carregar: ' + tplPgtPop_escapeHtml_(msg) + '</div>';\n      tplPgtPop_writeLog('Erro ao atualizar lista de controle: ' + msg, 'ERRO');\n    }\n  }\n\n  // ============================================================\n  // RENDER REAL (chamado pelo loader após o eval)\n  // ============================================================\n  function tplPgtPop_renderReal_() {\n    const container = document.getElementById('tplPgtPopContainer');\n    if (!container) return;\n    try {\n      container.innerHTML = TPL_PGTPOP_HTML_;\n      tplPgtPop_inicializar();\n    } catch (e) {\n      console.error('renderTplPgtPop_ falhou:', e);\n      container.innerHTML = '<div style=\"padding:24px;color:var(--bc-danger);background:var(--bc-danger-bg);border:1px solid var(--bc-danger-line);border-radius:6px;\">' +\n        'Não foi possível abrir esta tela. Recarregue a página (F5); se persistir, avise o administrador.</div>';\n    }\n  }\n</script>\n";

function PgtPop_obterConteudoModulo() {
  return PGTPOP_CONTEUDO_MODULO;
}
